// Generated by vibes-espmatter – the wall clock: SNTP sets it from MESP_NTP_SERVER (UTC; the time zone is
// set elsewhere, e.g. by the dashboard).
#include "espm_config.h"
#include "espm_ntp.h"

#include <ctime>
#include <esp_log.h>
#include <esp_netif_sntp.h>

static const char *TAG = "mesp_ntp";

/** Times before this are "not synced yet" (2025-01-01). */
#define VALID_TIME 1735689600

void mesp_ntp_start()
{
    esp_sntp_config_t config = ESP_NETIF_SNTP_DEFAULT_CONFIG(MESP_NTP_SERVER);
    esp_err_t err = esp_netif_sntp_init(&config);
    if (err != ESP_OK) ESP_LOGW(TAG, "SNTP: %s", esp_err_to_name(err));
}

bool mesp_time_synced()
{
    return time(nullptr) > VALID_TIME;
}
